import java.lang.annotation.*; import java.lang.reflect.*;
        public class AnnotationExamples { @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface MinLength{int value();} @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface JsonField{String value();} @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.TYPE) @interface Info{String author();String version() default "1.0";} @Info(author="Siddharth") static class User{@MinLength(3) @JsonField("user_name") String name="Java";} public static void main(String[]a)throws Exception{User u=new User();for(Field f:User.class.getDeclaredFields()){if(f.isAnnotationPresent(MinLength.class)){f.setAccessible(true);MinLength m=f.getAnnotation(MinLength.class);System.out.println(f.getName()+" valid="+(((String)f.get(u)).length()>=m.value()));}if(f.isAnnotationPresent(JsonField.class))System.out.println("json name="+f.getAnnotation(JsonField.class).value());}System.out.println(User.class.getAnnotation(Info.class).author());}}
